#:package Microsoft.CodeAnalysis.CSharp@4.14.0
//
// Splits the single NSwag-generated C# file into one file per top-level type.
//
//   dotnet run build/nswag/Split.cs -- <input.cs> <outputDir>
//
// NSwag always emits one monolithic file. This parses it with Roslyn, then writes each
// top-level type (class / interface / enum / record / struct / delegate) to its own file
// under <outputDir>, carrying over the file header (the <auto-generated> banner, #nullable
// and the #pragma warning disable block) and the namespace's `using System = global::System;`
// alias so every file still compiles on its own. Types that share a name (a type and its
// generic sibling, e.g. GvmsApiException / GvmsApiException<T>, or split partials) are kept
// together in one file. <outputDir> is wiped of *.cs first so deleted types do not linger.
//
using System.Text;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;
using Microsoft.CodeAnalysis.CSharp.Syntax;

if (args.Length < 2)
{
    Console.Error.WriteLine("usage: dotnet run Split.cs -- <input.cs> <outputDir>");
    return 1;
}

var inputPath = args[0];
var outputDir = args[1];

if (!File.Exists(inputPath))
{
    Console.Error.WriteLine($"input file not found: {inputPath}");
    return 1;
}

var source = File.ReadAllText(inputPath);
var tree = CSharpSyntaxTree.ParseText(source, new CSharpParseOptions(LanguageVersion.Preview));
var root = (CompilationUnitSyntax)tree.GetRoot();

var errors = tree.GetDiagnostics().Where(d => d.Severity == DiagnosticSeverity.Error).ToArray();
if (errors.Length > 0)
{
    Console.Error.WriteLine($"input file has {errors.Length} parse error(s); refusing to split:");
    foreach (var e in errors.Take(10)) Console.Error.WriteLine($"  {e}");
    return 1;
}

var namespaces = root.DescendantNodes().OfType<BaseNamespaceDeclarationSyntax>().ToArray();
if (namespaces.Length != 1)
{
    Console.Error.WriteLine($"expected exactly one namespace, found {namespaces.Length}");
    return 1;
}

var ns = namespaces[0];
var namespaceName = ns.Name.ToString();
var header = ns.GetLeadingTrivia().ToFullString().Replace("\r\n", "\n").TrimStart('\n');
var namespaceUsings = string.Concat(ns.Usings.Select(u => "    " + u.ToString().Trim() + "\n"));

var typeDeclarations = ns.Members
    .Where(m => m is BaseTypeDeclarationSyntax or DelegateDeclarationSyntax)
    .ToArray();

if (typeDeclarations.Length == 0)
{
    Console.Error.WriteLine("no top-level type declarations found");
    return 1;
}

var groups = typeDeclarations
    .GroupBy(NameOf, StringComparer.Ordinal)
    .OrderBy(g => g.Key, StringComparer.Ordinal)
    .ToArray();

Directory.CreateDirectory(outputDir);
foreach (var stale in Directory.EnumerateFiles(outputDir, "*.cs")) File.Delete(stale);

foreach (var group in groups)
{
    // NSwag already indents members for life inside a `namespace { }` block, so the member
    // text is emitted verbatim (trim only surrounding blank lines).
    var body = string.Join(
        "\n\n",
        group.Select(m => m.ToFullString().Replace("\r\n", "\n").Trim('\n')));

    var sb = new StringBuilder();
    sb.Append(header);
    if (!header.EndsWith('\n')) sb.Append('\n');
    sb.Append("namespace ").Append(namespaceName).Append("\n{\n");
    sb.Append(namespaceUsings);
    if (namespaceUsings.Length > 0) sb.Append('\n');
    sb.Append(body).Append('\n');
    sb.Append("}\n");

    File.WriteAllText(Path.Combine(outputDir, group.Key + ".cs"), sb.ToString(), new UTF8Encoding(false));
}

Console.WriteLine($"{typeDeclarations.Length} types -> {groups.Length} files in {outputDir}");
foreach (var group in groups) Console.WriteLine($"  {group.Key}.cs");
return 0;

static string NameOf(MemberDeclarationSyntax member) => member switch
{
    BaseTypeDeclarationSyntax t => t.Identifier.ValueText,
    DelegateDeclarationSyntax d => d.Identifier.ValueText,
    _ => throw new InvalidOperationException(),
};
